const test = require("node:test");
const assert = require("node:assert");
const { createStore } = require("./store.js");
const { purgeExpired } = require("./purge.js");

const DAY_MS = 24 * 60 * 60 * 1000;
const NOW = new Date("2026-09-19T00:00:00.000Z");
const daysAgo = (n) => new Date(NOW.getTime() - n * DAY_MS).toISOString();

test("purges sessions older than the retention period and keeps the rest", () => {
  const store = createStore([
    { id: "old", lastSeen: daysAgo(40) },
    { id: "recent", lastSeen: daysAgo(1) },
  ]);

  const removed = purgeExpired(store, NOW, 30);

  assert.strictEqual(removed, 1);
  assert.deepStrictEqual(
    store.all().map((s) => s.id),
    ["recent"],
  );
});

