const DAY_MS = 24 * 60 * 60 * 1000;

// Removes every session whose `lastSeen` is older than `days` before `now`,
// and returns how many rows went.
function purgeExpired(store, now, days) {
  const cutoff = now.getTime() - days * DAY_MS;
  const before = store.all().length;
  store.removeWhere((s) => new Date(s.lastSeen).getTime() < cutoff);
  return before - store.all().length;
}

module.exports = { purgeExpired };

